+	for _, pr := range results {
+		if pr != nil && pr.SyncModRes != nil && pr.Path == p {
+			return pr, results
+		}
+	}
+
+	pr := &GoModPathSyncResult{SyncModRes: &SyncModRes{Path: p}}
+
+	return pr, append(results, pr)
+}
